import {rapidBuildScenes} from './rapid-build-cases.js';
const delivery='d13-delivery-dependencies', interfaces='d13-interface-contracts', acceptance='d13-commissioning-complete-paths';
const c=(key,label,options)=>({key,label,options});
const s=(id,label,title,reference,objective,explanation,extra={})=>({id,label,title,reference,objective,pedagogical_role:'mechanism',explanation:[explanation],...extra});
export const learningContract=Object.freeze({driving_question:'How does a design become a tested, usable service?',fixed_boundary:'A 20 MW IT phase in ten 2 MW zones, ending at integrated service acceptance.',changed_variable:'Rack density, delivery bottlenecks, factory assembly and acceptance scope.',primary_payoff:'Connect equipment choices and factory work to the date at which tested racks can operate.',misconception:'Unchanged total MW means unchanged interfaces and delivery dates.',closing_question:'Which revised racks can operate, and which evidence is still missing?'});
export const initialState={intervention:'baseline',factoryWeeks:6,approvalWeek:0,factorySlotWeek:0,boundary:'coolant',rackKW:200,action:'unconfirmed',testPhase:'fault',coolingStart:21,electrical:false,hydraulic:false,geometry:false,logistics:false,controls:false,resources:false,diagnosis:'',showDiagnosis:false};
export const scenes=[
 s('delivery-purpose','EPC','Engineering, Procurement and Construction (EPC)',delivery,'D13.1','EPC covers engineering, procurement and construction. Commissioning verifies the installed system against its agreed requirements.',{pedagogical_role:'problem',titleOnly:true}),
 s('hardware-prices-meme','AI demand and hardware prices','AI demand and hardware prices',delivery,'D13.1','User-supplied hardware-price meme retained from the retired storage deck.',{pedagogical_role:'transition',imageOnly:true}),
 s('rack-case-brief','Case study: the rack changes','Case study: the rack design changes during construction',interfaces,'D13.2','A 20 MW IT phase is under construction. The rack design changes from 100 kW to 200 kW while total IT duty remains fixed.',{pedagogical_role:'problem'}),
 s('rack-change','Twenty megawatts, new racks','The same 20 MW is concentrated into half as many racks.',interfaces,'D13.2','Ten 2 MW zones change from twenty 100 kW racks per zone to ten 200 kW racks. The following three slides track what this change does to each electrical branch, coolant branch and support position.',{pedagogical_role:'comparison'}),
 s('electrical-interface','Rack change: electrical','The new rack exceeds its existing electrical branch rating.',interfaces,'D13.2','Continue the same 20 MW case. Balanced 480 V three-phase, PF 1, one full-duty supply path: 120.3 A at 100 kW becomes 240.6 A at 200 kW, exceeding the old allowable continuous 160 A. The rack count falls, but branch cables, terminals and protection must change.'),
 s('hydraulic-interface','Rack change: coolant','Doubling rack flow can quadruple the pressure drop.',interfaces,'D13.2','Continue the same 20 MW case. All IT heat enters water, cp 4.18 kJ/(kg·K), rise at most 10 K. Flow rises from 2.39 to 4.78 kg/s. Reused hardware with quadratic pressure-flow behavior requires 80 rather than 20 kPa, above the available 60 kPa. Whole-zone heat and flow remain unchanged.'),
 s('spatial-interface','Rack change: supports','The rack change concentrates the floor load at fewer positions.',interfaces,'D13.2','Continue the same 20 MW case. The vendor drawing stipulates twice the installed mass on the same four feet, equally shared. Half as many racks preserves zone mass but doubles occupied-position and foot loads. Check supports and anchorage against the revised drawing.'),
 s('schedule-case-brief','Case study: the opening date','Case study: what would bring the opening date forward?',delivery,'D13.1','A new phase needs electrical equipment, cooling equipment and utility power before integrated testing. Compare four delivery scenarios, including a delayed grid connection.',{pedagogical_role:'problem'}),
 s('critical-path','Spend effort on the bottleneck','Expediting cooling cannot recover a switchgear delay.',delivery,'D13.1','Compare all scenarios together. Baseline electrical readiness is week 23, cooling week 16 and utility week 16; four weeks of integrated testing ends in week 27. Expediting cooling by four weeks changes no acceptance date. Expediting electrical delivery by four weeks permits week 23 acceptance. A utility connection delayed to week 30 moves acceptance to week 34.',{pedagogical_role:'comparison'}),
 s('epc-and-prefab','EPC on a prefabricated project','EPC coordinates the design, purchases and construction of the plant.',delivery,'D13.2','For a prefabricated electrical plant, engineering sets the topology and connections, procurement orders the switchgear-transformer package, and construction prepares the foundations and installs the package. Prefabrication is a construction strategy, not a replacement for those responsibilities.'),
 s('factory-and-site','Assemble while the site is prepared','Prefabrication overlaps factory assembly with site construction.',delivery,'D13.2','Electrical and cooling components can arrive as tested assemblies with their internal distribution, manifolds, wiring and controls already installed. Civil works, utility access and foundations can proceed in parallel with this factory assembly. Site scope includes placement, field connections and integrated commissioning.'),
 {...rapidBuildScenes.find(item=>item.id==='aws-houdini-prefab'),title:'Project Houdini moves data-hall assembly into factories.',objective:'D13.1'},
 s('compass-package','A real electrical skid','Siemens and Compass combine switchgear and a transformer on one skid.',interfaces,'D13.2','Siemens and Compass co-developed a medium-voltage skid with 8DJH 36 switchgear and a transformer. Factory assembly consolidates the connection between these components into a repeatable package. The photograph shows its switchgear portion; the transformer is outside the frame.',{pedagogical_role:'case-study',sources:['https://www.siemens.com/en-us/company/insights/compass-datacenters-case-study/']}),
 s('interface-owner','Open Compute Project','Open Compute Project defines the interfaces between suppliers.',interfaces,'D13.2','The Open Compute Project publishes specifications for shared equipment interfaces. UQD-compliant couplings of the same nominal size interoperate, but the rack still needs sufficient branch flow and pressure. A common connector specification does not establish a complete rack cooling performance rating.',{pedagogical_role:'case-study',sources:['https://www.opencompute.org/documents/open-rack-base-specification-version-3-pdf','https://www.opencompute.org/documents/ocp-universal-quick-disconnect-uqd-specification-rev-1-0-2-pdf']}),
 s('factory-acceptance','Factory acceptance tests','Factory acceptance tests verify the module before shipment.',acceptance,'D13.3','FAT means factory acceptance test. It can check internal wiring, plumbing and controls against agreed criteria. Site cables, coolant joints and the final load path remain outside a test where those objects are absent. Shipment release and service acceptance have different evidence.'),
 s('controls-interface','Prove the action path','Commission the cooling-fault response of the revised racks.',interfaces,'D13.2','A cooling-fault signal must identify the rack, have defined units and freshness, reach an authorized action and provide observed confirmation. Remap alarms, circuits and reduction groups for the revised racks. The example does not prescribe a live operating procedure.',{controls:[c('action','Load reduction request',[['unconfirmed','No response confirmed'],['confirmed','Response measured']])]}),
 s('integrated-tests','Integrated acceptance','A failure test must show the required response at the rack.',acceptance,'D13.4','Follow one agreed cooling failure through physical fault, authorized command and measured response. Define numerical requirements, measurement points, response time and stop/accept criteria before execution. Normal duty, maintenance and recovery still need tests; their scenarios remain in the reader. Facilities test loads and application tests establish different evidence.',{controls:[c('testPhase','Follow the failure test',[['fault','1. Cooling fault'],['command','2. Command'],['measured','3. Measured response']])]}),
 s('accepted-paths','Count complete paths','The accepted systems must reach the same racks.',acceptance,'D13.3','Continue with the revised 100 racks at 200 kW, totaling 20 MW. Electrical acceptance covers A01–A80, cooling A21–A100 and network A01–A60. Their overlap is 40 racks, or 8 MW, assuming all other acceptance criteria met. Cooling extended to A01 gives 60 racks and 12 MW.',{controls:[c('coolingStart','Cooling acceptance',[[21,'A21–A100'],[1,'A01–A100']])]}),
 s('phase-boundary','Build beside an operating phase','A new phase can change a shared operating system.',acceptance,'D13.4','Teaching topology: A and future B share upstream plant and controls. Define live/construction boundaries, isolation ownership, shared capacity and required retests before connecting B. A prior acceptance record does not automatically accept a changed shared configuration.'),
 s('release-decision','Chapter 13 knowledge check','Which racks can operate now?',acceptance,'D13.4','The revised racks draw 200 kW each. Electrical A01–A80, cooling A21–A100 and network A01–A60 overlap at A21–A60. Only A21–A40 have a measured cooling-fault response that meets the agreed limits and timing. A41–A60 have a command acknowledgement but no confirmed rack response. All other acceptance criteria are met and operating records match the tested revision. Accept A21–A40: 20 racks and a 4 MW envelope. A41–A60 still need a measured response that passes. A01–A20 still need cooling evidence; A61–A100 still need network evidence, and A81–A100 also need electrical evidence. Handover includes the tested asset map, protection and control versions, limits, procedures, maintenance responsibilities, training and explicit disposition of open issues.',{pedagogical_role:'transfer'}),
];

export const sceneAliases=Object.freeze({
 'delivery-paths':'critical-path',
 'service-requirements':'controls-interface',
 'parallel-schedules':'factory-and-site',
 'manufacturing-release':'interface-owner',
 'module-transport':'factory-and-site',
 'release-holds':'electrical-interface',
 'approval-delay':'critical-path',
 'site-checks':'factory-acceptance',
 'handover-records':'release-decision',
});
export function resolveProcurementScene(hash){
 const id=sceneAliases[hash]||hash;
 const index=scenes.findIndex(scene=>scene.id===id);
 return index<0?0:index;
}
